# calls: repo2graph/cache.py::ResultCache.get (confidence 0.333), repo2graph/tasks.py::TaskManager.get (confidence 0.333), tests/test_http_transport.py::Server.get (confidence 0.333), .github/scripts/prod-igy.js::extractIssues, .github/scripts/prod-igy.js::detectType, .github/scripts/prod-igy.js::calculateSize, .github/scripts/prod-igy.js::detectAreas, .github/scripts/prod-igy.js::checkAgentsRules, .github/scripts/prod-igy.js::formatBotComment
