# called by: .github/scripts/summary.py::render
# calls: .github/scripts/summary.py::read_jsonl, repo2graph/cache.py::ResultCache.get (confidence 0.333), repo2graph/tasks.py::TaskManager.get (confidence 0.333), tests/test_http_transport.py::Server.get (confidence 0.333), .github/scripts/summary.py::top_hub_files.is_file
# calls (outside the repo): Counter, items, sort
# doc: [(node_id, in_degree), ...] for the top-n `file:`-type edge targets,     by raw in-degree across every edge type.
def top_hub_files(nodes_path: str, edges_path: str, n: int = TOP_N):
    """[(node_id, in_degree), ...] for the top-n `file:`-type edge targets,
    by raw in-degree across every edge type."""
    in_degree: Counter = Counter()
    for edge in read_jsonl(edges_path):
        dst = edge.get("dst")
        if dst:
            in_degree[dst] += 1
    if not in_degree:
        return []

    node_types = {}
    for node in read_jsonl(nodes_path):
        nid = node.get("id")
        if nid:
            node_types[nid] = node.get("type")

    def is_file(nid: str) -> bool:
        return nid.startswith("file:") or node_types.get(nid) == "file"

    hubs = [(nid, count) for nid, count in in_degree.items() if is_file(nid)]
    hubs.sort(key=lambda t: (-t[1], t[0]))
    return hubs[:n]

