    def _release(self) -> None:
        if sys.platform != "win32":
            try:
                import fcntl

                fcntl.flock(self._fh.fileno(), fcntl.LOCK_UN)
                return
            except ImportError:
                pass
        if self._locked_at is None:
            return
        if sys.platform == "win32":
            try:
                import msvcrt

                self._fh.seek(self._locked_at)
