    reuse = reuse or {}
    out: dict[str, list[float]] = {}
    todo = []
    for c in chunks:
        cid = c.get("id")
        if not cid:
            continue
        known = reuse.get(cid)
        if known is not None:
            out[cid] = [float(x) for x in known]
        else:
            todo.append(c)
    step = max(1, int(batch))
