def repo_context(root: Path) -> dict:
    """Repo-level facts used to resolve imports (currently the Go module path)."""
    ctx: dict = {}
    gomod = root / "go.mod"
    if gomod.exists():
        for line in gomod.read_text("utf8", "replace").splitlines():
            if line.startswith("module "):
